(function(root){
'use strict';
const q=(id,prompt,options,correct,explanation,graph)=>({id,prompt,options:options.map(([id,label])=>({id,label})),correct:[correct],explanation,graph});
const dots=values=>({type:'dots',values,caption:'Each dot is one observation. Repeated values stack vertically.'});
const table=(headers,rows,caption)=>({type:'table',headers,rows,caption});
const LESSONS=[
 {id:'distributions',short:'Data & distributions',title:'What does a distribution show?',goal:'Identify the variable, its units, and the pattern across observations.',
  controls:[{name:'shape',label:'Illustrative data',options:[['symmetric','One central cluster'],['skew','A long right tail'],['split','Two clusters']]},{name:'shift',label:'Add minutes to every observation',min:0,max:6,step:1}],defaults:{shape:'symmetric',shift:0},motion:{key:'shift',end:6,replay:0},
  steps:[
   {title:'Start with what was measured.',text:'An observation is one recorded case. A variable is what changes across cases. Minutes spent waiting is quantitative; a travel-method category is categorical. A dot plot makes sense for the measured waiting times, with the horizontal axis in minutes.',try:'Read the horizontal axis and count the observations before describing a pattern.'},
   {title:'Frequency is a count, not a value.',text:'Each dot represents one observation. Three dots above 3 mean three observations equal 3 minutes. The vertical stacking records frequency; it does not mean the waiting time is 3 units higher.',try:'Select one central cluster. Which value appears most often?'},
   {title:'Describe more than a center.',text:'Compare shape, center, spread, and unusual values. A right tail extends toward larger measurements. Two clusters may suggest groups worth investigating; the picture alone does not tell us why they formed.',try:'Switch between the three examples. Describe the tail or clusters without inventing their cause.'},
   {title:'Keep the measurement scale visible.',text:'Adding the same number to every observation shifts the location but keeps all pairwise distances the same. Dot heights count repetitions; neither horizontal position nor dot height is a probability unless a denominator is supplied.',try:'Shift the data by 2. Explain what changes and what stays the same.'}
  ],
  predict:q('ae-p1','These are waiting times in minutes. What do the three dots above 3 mean?',[['count','Three observations each lasted 3 minutes.'],['sum','One observation lasted 9 minutes.'],['height','The waiting time is the dot’s vertical height.']],'count','The horizontal position gives the measured time; stacking shows how many cases have that value.',dots([1,2,2,3,3,3,4,5])),
  checks:[q('ae-c1','How many observations are at most 2 minutes?',[['3','3'],['2','2'],['4','4']],'3','There is one dot at 1 and two dots at 2: three observations in total.',dots([1,2,2,3,4,4,7])),q('ae-c2','Which description fits these observations?',[['right','A central cluster with a tail toward larger values.'],['symmetric','A symmetric pattern around 4.'],['cause','The largest time proves someone was careless.']],'right','Most times are between 2 and 5; the larger values extend the right tail. A cause is not established by the plot.',dots([2,3,3,4,4,5,9,13]))],next:'Compare two new distributions using shape, center, spread, and measurement units.'},
 {id:'center',short:'Center & spread',title:'Which summary keeps the important information?',goal:'Compare mean, median, and spread, including sensitivity to a large observation.',
  controls:[{name:'tail',label:'Largest observation (minutes)',min:6,max:30,step:1}],defaults:{tail:8},motion:{key:'tail',end:30,replay:6},
  steps:[
   {title:'The mean shares the total equally.',text:'The mean is the sum divided by the number of observations. For 1, 2, 2, 3, 12, the total is 20 across five cases, so the mean is 4. A mean need not be an observed value.',try:'Move the largest observation. Watch both the total and the mean.'},
   {title:'The median uses the sorted position.',text:'The median is the middle sorted observation, or the average of the two middle observations for an even count. In 1, 2, 2, 3, 12, the median is 2. A larger maximum can pull the mean upward while the middle value stays unchanged.',try:'Explain why moving only the largest of these nine observations leaves the median at 4.'},
   {title:'A center does not show all variation.',text:'The range is maximum minus minimum. Two data sets can share a mean or median but have different spreads. Standard deviation measures spread around the mean; its sample and population formulas use different divisors. We do not calculate it in these lessons.',try:'Compare the smallest and largest observations, then calculate the range.'},
   {title:'Choose a summary for the question.',text:'A resistant center such as the median can describe a typical case when there is a long tail. The mean remains useful for totals and averages across all cases. Neither choice permits removing an inconvenient observation without investigating it.',try:'Describe a situation where the mean and median answer different questions.'}
  ],
  predict:q('ae-p2','For these five values, which pair is correct?',[['pair','Mean = 4; median = 2.'],['same','Mean = 2; median = 2.'],['swap','Mean = 2; median = 4.']],'pair','The total is 20, so the mean is 4. The middle sorted value is 2.',dots([1,2,2,3,12])),
  checks:[q('ae-c3','For 2, 4, 4, 6, what is the median?',[['4','4'],['6','6'],['8','8']],'4','There are four values, so average the two middle values: (4 + 4)/2 = 4.',dots([2,4,4,6])),q('ae-c4','Replace 9 with 29 in this data set. What happens?',[['change','The mean and range increase; the median stays 4.'],['all','Every summary increases by 20.'],['median','Only the median increases.']],'change','Only one of five values increases by 20, so the mean increases by 4. The range increases by 20. The middle value stays 4.',dots([2,3,4,5,9]))],next:'Find two data sets with the same center but different spreads, and justify which summaries to report.'},
 {id:'studies',short:'Sampling & causation',title:'Who was included, and what was assigned?',goal:'Separate random selection, random assignment, and unsupported causal claims.',
  controls:[{name:'sampling',label:'Selection method',options:[['volunteer','Volunteers reached in one dorm'],['random','Random selection from all students']]},{name:'design',label:'Study design',options:[['observational','Observe existing study habits'],['assigned','Randomly assign a study method']]}],defaults:{sampling:'volunteer',design:'observational'},
  steps:[
   {title:'Name the target population.',text:'A sample is the group measured; a population is the group we want to describe. A dorm-based volunteer survey may miss commuters and people who decline. A larger sample does not by itself repair an incomplete sampling frame or nonresponse bias.',try:'Compare the campus population with the illustrative selected group. Who may be missing?'},
   {title:'Random selection concerns generalization.',text:'Random selection from an adequate population list gives cases a known chance of inclusion. It supports population estimation, with sampling uncertainty and possible nonresponse still considered. One balanced-looking sample is not proof of random selection; a random sample need not be exactly balanced.',try:'Switch selection methods. Read the method, not just the two bar heights.'},
   {title:'Random assignment concerns causation.',text:'Random assignment determines who receives which treatment. In a well-run experiment it helps balance confounding factors and supports a causal comparison. It does not make volunteers representative of all students. Random selection and random assignment do different jobs.',try:'Keep volunteer selection and switch to random assignment. Which claim improves, and which limitation remains?'},
   {title:'An association needs a careful claim.',text:'Students who choose longer study hours may also differ in preparation or motivation. A relationship between hours and scores does not isolate a causal effect. A study description must support both the intended population and the proposed cause.',try:'Explain why observing a difference is not the same as assigning a treatment.'}
  ],
  predict:q('ae-p3','A college asks only volunteers in one dorm about travel to campus. Can this reliably describe all students?',[['limited','The selection may miss commuters and non-volunteers.'],['all','Yes, if at least 100 people respond.'],['causal','Yes, volunteering creates a randomized experiment.']],'limited','Dorm volunteers may differ systematically from the full campus population. Sample size alone does not remove selection bias.',table(['Group','Campus population'],[['Dorm residents',50],['Commuters',50]],'A toy population of 100 students; the survey is offered only in one dorm.')),
  checks:[q('ae-c5','A school randomly samples students, then observes their existing sleep hours and scores. What is justified?',[['estimate','Population estimates may be supported, but sleep was not randomly assigned.'],['cause','Random selection proves sleep causes the score difference.'],['none','Random sampling gives no useful information.']],'estimate','Random sampling concerns the population. This observational comparison can still be confounded.',table(['Selection','Treatment'],[['Random sample from the school','Existing sleep habits observed']],'No sleep schedule was assigned.')),q('ae-c6','Volunteers are randomly assigned to two teaching methods. Which claim is most careful?',[['cause','A well-run trial can support a causal comparison for participants; wider generalization needs care.'],['population','All students are represented because assignment was random.'],['observe','This is purely observational because the participants volunteered.']],'cause','The methods were assigned at random, while the participating sample remains voluntary.',table(['Recruitment','Method assignment'],[['Volunteers','Random assignment to A or B']],'Recruitment and treatment assignment are separate steps.'))],next:'For a new study, name the population, selection method, treatment assignment, and plausible confounders.'},
 {id:'probability',short:'Probability & conditions',title:'Which group belongs in the denominator?',goal:'Separate an intersection from a conditional probability using a two-way table.',
  controls:[{name:'overlap',label:'Club members who passed',min:2,max:18,step:1},{name:'condition',label:'Reference group',options:[['all','All 100 students'],['club','Only the 20 club members']]}],defaults:{overlap:12,condition:'all'},motion:{key:'overlap',end:18,replay:2},
  steps:[
   {title:'Start with a defined experiment.',text:'In this example one student is selected uniformly at random from the 100 listed students. Each student has the same chance. Counting favorable cases and dividing by total cases is appropriate here; equally likely outcomes cannot be assumed in every experiment.',try:'Count all students and then count those who both joined the club and passed.'},
   {title:'An intersection keeps the original whole.',text:'P(club and pass) uses all 100 students as the denominator. With 12 students in the intersection, it is 12/100 = 0.12. The word “and” asks for the overlap, rather than adding the two event counts.',try:'Keep the reference group at all students and move the overlap control.'},
   {title:'A condition changes the reference group.',text:'P(pass given club) considers only the 20 club members. With 12 who passed, it is 12/20 = 0.60. The numerator can stay the same while the denominator changes. Conditional probabilities in opposite directions generally differ.',try:'Switch the reference group to club members and explain the denominator.'},
   {title:'Independence is a comparison.',text:'For events with a nonzero conditioning probability, independence means P(pass given club) = P(pass). Here 30 of 100 students passed. When 6 of the 20 club members pass, both probabilities equal 0.30. Club membership and passing are then independent in this toy table; this is not a causal claim.',try:'Set the overlap to 6 and compare conditional and overall passing probabilities.'}
  ],
  predict:q('ae-p4','One of these 40 students is selected uniformly at random. What is P(pass given club)?',[['conditional','6/10'],['joint','6/40'],['reverse','6/20']],'conditional','The condition limits the reference group to the 10 club members. Six of those 10 passed.',table(['','Passed','Did not pass'],[['Club',6,4],['No club',14,16]],'Rows and columns divide the same 40 students into non-overlapping cells.')),
  checks:[q('ae-c7','One of these 50 students is selected uniformly at random. What is P(club and pass)?',[['joint','8/50'],['condition','8/20'],['sum','20/50']],'joint','Eight students satisfy both events; the reference group is all 50 students.',table(['','Passed','Did not pass'],[['Club',8,12],['No club',10,20]],'A new table of 50 students.')),q('ae-c8','In this table, are passing and club membership independent?',[['yes','Yes: P(pass given club) = P(pass) = 1/2.'],['no','No: events cannot overlap if they are independent.'],['cause','Yes: the club caused half its members to pass.']],'yes','Among club members 5/10 passed; overall 20/40 passed. The probabilities match. Independence permits overlap and does not imply causation.',table(['','Passed','Did not pass'],[['Club',5,5],['No club',15,15]],'A new table of 40 students.'))],next:'Use a new two-way table to compare joint probability, both conditional directions, and independence.'}
];
const api={MODULE:'ae01',TITLE:'Statistics foundations',VERSION:'ae01-beta-0.1',eyebrow:'STATISTICS FOUNDATIONS · DATA, DESIGN, AND UNCERTAINTY',headline:'Read the data.\nCheck the claim.',lead:'Explore patterns, compare summaries, and ask which group a claim describes. Explain your choices before and after each lesson.',prerequisite:'Comfortable with fractions and percentages? You can start here.',scope:'Selected introductory statistics and probability; inference procedures come later.',bridge:{href:'../../../foundations/?module=ae01',label:'Check statistics foundations · 15 questions →'},LESSONS};
if(typeof module==='object'&&module.exports)module.exports=api;else root.ClueveraCourseContent=api;
})(typeof window==='undefined'?globalThis:window);
